  /* ------------------------------------------------------------ 헬퍼 */

  function text(def) {
    def.type = 'text';
    def.fontFamily = def.fontFamily || FONT;
    return def;
  }

  function rect(def) {
    def.type = 'rect';
    return def;
  }

  function gradientRect(def) {
    def.type = 'rect';
    return def;
  }

  function background(def) {
    def.type = 'rect';
    def.kind = 'bg';
    return def;
  }

  function slot(def) {
    def.type = 'slot';
    return def;
  }

  function guide(def) {
    def.type = 'rect';
    def.isGuide = true;
    def.fill = 'rgba(0,0,0,0)';
    def.stroke = '#94a3b8';
    def.strokeWidth = 1;
    def.strokeDashArray = [7, 5];
    return def;
  }

  function image(def) {
    def.type = 'image';
    def.kind = 'image';
    return def;
  }

  function icon(def) {
    def.type = 'icon';
    return def;
  }

  function figure(def) {
    def.type = 'figure';
    return def;
  }

  function circle(def) {
    def.type = 'circle';
    return def;
  }

  function path(def) {
    def.type = 'path';
    return def;
  }

  function grad(angle, stops) {
    return { angle: angle, stops: stops };
  }

